import{_ as e,o as t,c as n,a3 as s}from"./chunks/framework.I6s8z2kk.js";const p=JSON.parse('{"title":"Getting around the admin panel","description":"","frontmatter":{},"headers":[],"relativePath":"user/admin/getting-around.md","filePath":"user/admin/getting-around.md"}'),r={name:"user/admin/getting-around.md"};function i(o,a,d,h,l,c){return t(),n("div",null,[...a[0]||(a[0]=[s('<h1 id="getting-around-the-admin-panel" tabindex="-1">Getting around the admin panel <a class="header-anchor" href="#getting-around-the-admin-panel" aria-label="Permalink to &quot;Getting around the admin panel&quot;">​</a></h1><p>The admin panel is for platform staff (<strong>system users</strong>). What you can see and do depends on the <strong>role</strong> you were given. If a section is missing or an action is refused, ask an administrator to check your role.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Sign in with your email and password. Inactive users cannot sign in.</p><h2 id="what-you-can-manage" tabindex="-1">What you can manage <a class="header-anchor" href="#what-you-can-manage" aria-label="Permalink to &quot;What you can manage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Page</th></tr></thead><tbody><tr><td>Centers, their services, reservations and purchases</td><td><a href="./centers">Centers</a></td></tr><tr><td>Client accounts</td><td><a href="./clients">Clients</a></td></tr><tr><td>Discounts, campaigns and coupons</td><td><a href="./promotions">Promotions</a></td></tr><tr><td>What clients see first in the app</td><td><a href="./homepage">Homepage</a></td></tr><tr><td>Push and WhatsApp messages</td><td><a href="./notifications">Notifications</a></td></tr><tr><td>Plans and center subscriptions</td><td><a href="./billing">Plans and subscriptions</a></td></tr><tr><td>Fees, payments and center payouts</td><td><a href="./payments-payouts">Purchases, fees and payouts</a></td></tr><tr><td>Dashboards and spreadsheets</td><td><a href="./analytics">Analytics and exports</a></td></tr><tr><td>Staff accounts, roles, cities and tags</td><td><a href="./users-roles">Users and roles</a></td></tr></tbody></table><h2 id="legal-pages" tabindex="-1">Legal pages <a class="header-anchor" href="#legal-pages" aria-label="Permalink to &quot;Legal pages&quot;">​</a></h2><p><strong>Settings → Legal pages</strong> holds the privacy policy and terms and conditions of the client app and of the center app, each in English and Arabic. Write them in the editor (headings, lists, links, alignment) and <strong>Save</strong>; both languages are required. The apps open the published page right away. Use <strong>Open page</strong> to see it as clients and centers do. You need the <strong>Legal documents</strong> permission (<code>legal_documents.manage</code>).</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>The bell shows platform events (for example a new center registering). Mark one or all as read.</p><h2 id="lists" tabindex="-1">Lists <a class="header-anchor" href="#lists" aria-label="Permalink to &quot;Lists&quot;">​</a></h2><p>Lists are paged and can be searched and filtered. Large lists can be exported to a spreadsheet; see <a href="./analytics">Analytics and exports</a>.</p><h2 id="the-documentation" tabindex="-1">The documentation <a class="header-anchor" href="#the-documentation" aria-label="Permalink to &quot;The documentation&quot;">​</a></h2><p>Staff with the <strong>API docs</strong> permission can also open these guides and the technical endpoint reference. Use <strong>Sign out</strong> in the top bar when you are done.</p>',14)])])}const u=e(r,[["render",i]]);export{p as __pageData,u as default};
